// Embeds the GTFS text files in js/data-bundle.js so the app also works when
// index.html is opened directly from disk (file://), where fetch() is blocked.
const fs = require('fs'), path = require('path');
const dir = path.join(__dirname, '..', 'data', 'gtfs'), o = {};
['stops.txt', 'routes.txt', 'trips.txt', 'stop_times.txt', 'frequencies.txt'].forEach(f => o[f] = fs.readFileSync(path.join(dir, f), 'utf8'));
fs.writeFileSync(path.join(__dirname, '..', 'js', 'data-bundle.js'),
  '/* Generated by tools/bundle_data.js from data/gtfs/. Do not edit by hand. */\nwindow.GTFS_BUNDLE = ' + JSON.stringify(o) + ';\n');
console.log('js/data-bundle.js written');
